customer = args.get("customer")
items = args.get("items") or []
due_date = args.get("due_date")

if not frappe.db.exists("Customer", customer):
    # Don't fail outright -- propose creating the missing Customer first,
    # then automatically retry this same request once that's done. The
    # user still approves each step in the Agent Caller page; nothing
    # here runs without a click.
    result = {
        "created": False,
        "error": f"Customer '{customer}' does not exist.",
        "next_action": {
            "name": "create_customer",
            "arguments": {"customer_name": customer},
        },
        "then": {
            "name": "create_sales_order",
            "arguments": args,
        },
    }
else:
    missing_items = [i["item_name"] for i in items if not frappe.db.exists("Item", i.get("item_name"))]
    if missing_items:
        names = ", ".join(missing_items)
        result = {"created": False, "error": f"Item(s) not found: {names}"}
    else:
        doc = frappe.get_doc({
            "doctype": "Sales Order",
            "customer": customer,
            "delivery_date": due_date or frappe.utils.add_days(frappe.utils.nowdate(), 7),
            "items": [{"item_code": i["item_name"], "qty": i.get("qty", 1)} for i in items],
        })
        doc.insert()
        result = {"created": True, "name": doc.name, "doctype": "Sales Order"}

